1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: 'quote';
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: 'claim';
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult =
36	  | { premium: number }
37	  | { payout: number; remainingCap: number };
38	
39	export interface ScenarioOutput {
40	  results: StepResult[];
41	}
42	
43	const PROCESSING_FEE = 5;
44	const FIRST_INSURANCE_SURCHARGE = 0.1;
45	const CURSE_SURCHARGE = 0.5;
46	const HIGH_ENCHANTMENT_LEVEL = 5;
47	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
48	const LOYALTY_YEARS = 2;
49	const LOYALTY_DISCOUNT = 0.2;
50	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
51	const COMPONENT_BASE_PREMIUM = 25;
52	const BLOCK_SIZE = 3;
53	const BLOCK_BASE_PREMIUM = 60;
54	const COMPONENT_INSURANCE_VALUE = 250;
55	const CAP_MULTIPLIER = 2;
56	const DEDUCTIBLE = 100;
57	const HIGH_ENCHANTMENT_CLAIM_LEVEL = 8;
58	const HIGH_ENCHANTMENT_REIMBURSEMENT = 0.5;
59	
60	const MAIN_ITEM_INSURANCE_VALUE: Record<string, number> = {
61	  sword: 1000,
62	  amulet: 600,
63	  staff: 800,
64	  potion: 400,
65	};
66	
67	const MAIN_ITEM_BASE_PREMIUM: Record<string, number> = {
68	  sword: 100,
69	  amulet: 60,
70	  staff: 80,
71	  potion: 40,
72	};
73	
74	const COMPONENT_TYPES = new Set(['rune', 'moonstone']);
75	
76	function isComponent(type: string): boolean {
77	  return COMPONENT_TYPES.has(type);
78	}
79	
80	function isKnownType(type: string): boolean {
81	  return type in MAIN_ITEM_BASE_PREMIUM || isComponent(type);
82	}
83	
84	function basePremiumOf(item: Item): number {
85	  return isComponent(item.type)
86	    ? COMPONENT_BASE_PREMIUM
87	    : MAIN_ITEM_BASE_PREMIUM[item.type];
88	}
89	
90	/**
91	 * Components of the same type are priced in blocks: a group of exactly
92	 * BLOCK_SIZE alike components costs BLOCK_BASE_PREMIUM instead of the
93	 * per-component rate. Other counts are priced per component.
94	 */
95	function policyBasePremium(items: Item[]): number {
96	  const componentCounts = new Map<string, number>();
97	  let total = 0;
98	
99	  for (const item of items) {
100	    if (isComponent(item.type)) {
101	      componentCounts.set(
102	        item.type,
103	        (componentCounts.get(item.type) ?? 0) + 1,
104	      );
105	    } else {
106	      total += basePremiumOf(item);
107	    }
108	  }
109	
110	  for (const count of componentCounts.values()) {
111	    total +=
112	      count === BLOCK_SIZE
113	        ? BLOCK_BASE_PREMIUM
114	        : count * COMPONENT_BASE_PREMIUM;
115	  }
116	
117	  return total;
118	}
119	
120	function quotePremium(
121	  items: Item[],
122	  customer: Customer,
123	  previousContracts: number,
124	): number {
125	  const policyBase = policyBasePremium(items);
126	  const itemSurcharges = items.reduce((sum, item) => {
127	    const base = basePremiumOf(item);
128	    const curse = item.cursed ? base * CURSE_SURCHARGE : 0;
129	    const enchanted =
130	      (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL
131	        ? base * HIGH_ENCHANTMENT_SURCHARGE
132	        : 0;
133	    return sum + curse + enchanted;
134	  }, 0);
135	  const firstInsurance = policyBase * FIRST_INSURANCE_SURCHARGE;
136	  const loyalty =
137	    customer.yearsWithMHPCO >= LOYALTY_YEARS
138	      ? policyBase * LOYALTY_DISCOUNT
139	      : 0;
140	  const followUp =
141	    previousContracts > 0 ? policyBase * FOLLOW_UP_CONTRACT_DISCOUNT : 0;
142	  return Math.ceil(
143	    policyBase +
144	      itemSurcharges +
145	      firstInsurance -
146	      loyalty -
147	      followUp +
148	      PROCESSING_FEE,
149	  );
150	}
151	
152	interface Policy {
153	  items: Item[];
154	  remainingCap: number;
155	}
156	
157	function insuranceSum(items: Item[]): number {
158	  return items.reduce(
159	    (sum, item) =>
160	      sum +
161	      (isComponent(item.type)
162	        ? COMPONENT_INSURANCE_VALUE
163	        : MAIN_ITEM_INSURANCE_VALUE[item.type]),
164	    0,
165	  );
166	}
167	
168	function settleClaim(policy: Policy, damages: Damage[]): StepResult {
169	  let desired = 0;
170	  // Each damage entry must name a distinct insured item, so two damages of
171	  // one type are only valid when two such items are covered.
172	  const unclaimed = [...policy.items];
173	
174	  for (const damage of damages) {
175	    if (damage.amount < 0) {
176	      throw new Error(
177	        `negative damage amount for ${damage.itemType}: ${damage.amount}`,
178	      );
179	    }
180	
181	    const index = unclaimed.findIndex((i) => i.type === damage.itemType);
182	    if (index === -1) {
183	      throw new Error(`item not covered by this policy: ${damage.itemType}`);
184	    }
185	    const [item] = unclaimed.splice(index, 1);
186	
187	    const reimbursable =
188	      (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_LEVEL
189	        ? damage.amount * HIGH_ENCHANTMENT_REIMBURSEMENT
190	        : damage.amount;
191	    desired += Math.max(0, reimbursable - DEDUCTIBLE);
192	  }
193	
194	  const payout = Math.floor(Math.min(desired, policy.remainingCap));
195	  policy.remainingCap -= payout;
196	  return { payout, remainingCap: policy.remainingCap };
197	}
198	
199	export function runScenario(scenario: Scenario): ScenarioOutput {
200	  const results: StepResult[] = [];
201	  const policies = new Map<number, Policy>();
202	  let contracts = 0;
203	
204	  scenario.steps.forEach((step, index) => {
205	    if (step.op === 'quote') {
206	      for (const item of step.items) {
207	        if (!isKnownType(item.type)) {
208	          throw new Error(`unknown item type: ${item.type}`);
209	        }
210	      }
211	      results.push({
212	        premium: quotePremium(step.items, scenario.customer, contracts),
213	      });
214	      contracts += 1;
215	      policies.set(index, {
216	        items: step.items,
217	        remainingCap: insuranceSum(step.items) * CAP_MULTIPLIER,
218	      });
219	    } else {
220	      results.push(
221	        settleClaim(policies.get(step.policy)!, step.incident.damages),
222	      );
223	    }
224	  });
225	
226	  return { results };
227	}
